 private const string Hero="mou:ju-shou",Plain="fixture:mjs-anniv-plain",Quiet="fixture:mjs-anniv-quiet",Driver="fixture:mjs-anniv-driver",Deck="fixture:mjs-anniv-deck";
 public static void ActualDrawChoiceUseOnlyEntityExpiryAndPaidCold()
 {
  var registry=ContentRegistry.Build(new StandardContentPackage(),new Fixture());
  var setup=new ShanheBattleSetup(7,1,"mou-ju-shou-anniversary-native",Hero,Hp:3,MaxHpBonus:0,InitialHandBonus:0,DrawBonus:0,SlashBonus:0,ExtraSkillIds:[Driver],StartingCards:[new(CardKind.Dodge,Suit.Heart,2),new(CardKind.Dodge,Suit.Heart,3),new(CardKind.Dodge,Suit.Heart,4)],StartingEquipment:[],EnemyRoster:[new(Plain,Hp:12){StartingHand=[]},new(Plain,Hp:12){StartingHand=[]}],AllyRoster:[new(Plain,Hp:12){StartingHand=[]}],CampaignHash:new string('a',64));
  var game=GameEngine.CreateStandard(new(){Seed=setup.BattleSeed,PlayerCount=4,HumanSeat=0,HumanRole=null,HumanTeamId=ShanheBattleSetup.PlayerTeamId,ModeId=ShanheBattleSetup.BattleModeId,ShanheBattle=setup,UseInteractiveSetup=false,UseInteractiveDiscard=false,AdvanceAfterHumanCommands=false,MaxTurns=12},registry);
  PendingDecision? P()=>Enumerable.Range(0,4).Select(s=>game.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p is not null);
  PlayerSnapshot V(int seat=0)=>game.CreateSnapshot(0).Players[seat];T[] E<T>()=>game.Events.Select(e=>e.Payload).OfType<T>().ToArray();
  ProgramSkillFrame? F()=>game.ResolutionStack.OfType<ProgramSkillFrame>().LastOrDefault(f=>f.MouJuShou is not null);
  string Diagnostic()=>JsonSerializer.Serialize(new{game.State.TurnNumber,game.State.CurrentSeat,game.State.Phase,Prompt=P(),Players=game.CreateSnapshot(0).Players.Select(p=>new{p.Seat,p.Hp,p.HandCount,p.Hand,p.Equipment}),Frames=game.ResolutionStack.Select(f=>JsonSerializer.Serialize(f,f.GetType())),Facts=game.Events.TakeLast(30).Select(e=>JsonSerializer.Serialize(e.Payload,e.Payload.GetType()))});
  void Need(bool yes,string text){if(!yes)throw new InvalidOperationException(text+Diagnostic());}
  void Submit(GameCommand command){try{var result=game.Submit(CommandJson.Deserialize(CommandJson.Serialize([command])).Single());Need(result.Accepted,result.Error?.Message??"Actual native command rejected.");}catch(Exception ex){throw new InvalidOperationException(ex.Message+Diagnostic(),ex);}}
  void Answer(Func<PromptChoice,bool> match){var p=P();Need(p?.PlayerSeat==0,"The actual recipient is the Human chooser.");var c=p!.Choices.FirstOrDefault(match);Need(c is not null,"The required actual Zuo Jun choice is published.");Submit(new AnswerPromptCommand(0,p.PromptId,c!.Id,game.Revision));}
  void Reach(Func<bool> done,[CallerLineNumber]int line=0){for(var i=0;i<150;i++){if(done())return;Need(game.State.Winner==Winner.None,"Unexpected terminal result at "+line);if(P()is{PlayerSeat:0})throw new InvalidOperationException("Unexpected actual Human boundary at "+line+Diagnostic());Submit(new AdvanceOneStepCommand(game.Revision));}throw new InvalidOperationException("Bounded actual Ju Shou flow not reached at "+line+Diagnostic());}
  void Play()=>Reach(()=>P()is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
  void StartZuoJun(){Submit(new UseProgramSkillCommand(0,"mou:zuojun","draw-and-choose",[],[0],game.Revision,P()!.PromptId));Reach(()=>F()?.MouJuShou?.Stage==MouJuShouStage.Choice&&P()?.PlayerSeat==0);}
  void Penalty(){Reach(()=>F()?.MouJuShou?.Stage==MouJuShouStage.Penalty&&P()?.PlayerSeat==0);var cost=V().Hand.First(c=>c.Kind==CardKind.Dodge).Id;Answer(c=>c.Cards.SequenceEqual([cost]));Play();Need(game.CardMovements.Any(m=>m.CardId==cost&&m.From==CardLocation.Hand(0)&&m.To==CardLocation.DiscardPile)&&E<NativeLogicalDiscardInvocationRecordedEvent>().Any(e=>e.TurnNumber==game.State.TurnNumber&&e.ExecutorSeat==0&&e.ActualCount==1&&e.Reason.Value=="skill-program.mou:muwang.discard"),"The actual second owned departure pays one genuine logical discard without inventing another loss from Processing.");}
  Submit(new StartGameCommand());Play();var turn=game.State.TurnNumber;StartZuoJun();var keepFrame=F()!.Id;var kept=F()!.MouJuShou!.Bound.ToArray();
  Need(kept.Length==3&&kept.All(id=>V().Hand.Any(c=>c.Id==id))&&E<MouJsDrawReturnedEvent>().Single(e=>e.FrameId==keepFrame)is{Requested:3,Actual:3},"Zuo Jun binds the three genuine native Draw entities before the recipient privately chooses.");
  Answer(c=>c.Parameters.GetValueOrDefault("branch")=="keep");Play();
  Need(E<MouJsGrantEvent>()is[{Recipient:0,Count:3}]&&kept.All(id=>V().Hand.Single(c=>c.Id==id).SkillMarkLabel?.Contains("佐军")==true)&&!game.GetHumanLegalActions().Any(a=>a.CardId is{}id&&kept.Contains(id))&&!game.GetHumanLegalActions().Any(a=>a.ProgramSkillId=="mou:zuojun"),"The preserved actual entities are marked and cannot be used, and the genuine per-Play activation is spent.");
  var dropped=kept[0];var pair=new[]{dropped,V().Hand.First(c=>c.Kind==CardKind.Dodge).Id};Submit(new UseProgramSkillCommand(0,Driver,"drop-pair",pair,[],game.Revision,P()!.PromptId));Reach(()=>F()?.MouJuShou?.Stage==MouJuShouStage.FirstLossChoice&&P()?.PlayerSeat==0);
  Need(F()!.MouJuShou!.Bound.Order().SequenceEqual(pair.Order())&&pair.All(id=>!V().Hand.Any(c=>c.Id==id))&&E<MouJsFirstChosenEvent>().Length==0,"One original native loss batch freezes both actually lost eligible entities and lets Ju Shou choose one instead of choosing by movement enumeration.");
  var firstOwner=SnapshotJson.Serialize(game.CreateSnapshot(0));var firstPeer=SnapshotJson.Serialize(game.CreateSnapshot(2));var firstMoves=game.CardMovements.Count;game=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(game.CreateCheckpoint())),registry);
  Need(firstOwner==SnapshotJson.Serialize(game.CreateSnapshot(0))&&firstPeer==SnapshotJson.Serialize(game.CreateSnapshot(2))&&F()?.MouJuShou is{Stage:MouJuShouStage.FirstLossChoice}selection&&selection.Bound.Order().SequenceEqual(pair.Order())&&game.CardMovements.Count==firstMoves&&E<MouJsFirstChosenEvent>().Length==0,"A representative new-pending Cold retains the exact private first-batch choice without moving or selecting a primary entity twice.");
  Answer(c=>c.Cards.SequenceEqual([dropped]));Play();
  Need(game.CardMovements.Count(m=>m.CardId==dropped&&m.From==CardLocation.Hand(0)&&m.To==CardLocation.DiscardPile)==1&&!V().Hand.Any(c=>c.Id==dropped&&c.SkillMarkLabel?.Contains("佐军")==true)&&V().Hand.Any(c=>c.Id==dropped)&&E<MouJsFirstChosenEvent>()is[{CardId:var chosen}]&&chosen==dropped&&E<MouJsRecoveredEvent>()is[{CardId:var returned}]&&returned==dropped&&!V().Hand.Any(c=>c.Id==pair[1])&&game.GetHumanLegalActions().Any(a=>a.CardId==dropped),"A genuine departure clears only that entity's original Zuo Jun property immediately; Muwang returns only the chosen exact entity without restoring its old use ban or exemption.");
  Submit(new UseProgramSkillCommand(0,Driver,"drop",[dropped],[],game.Revision,P()!.PromptId));Penalty();Need(E<MouJsRecoveredEvent>().Length==1&&E<MouJsMuwangQueuedEvent>().Count(e=>e.Turn==turn&&e.Kind==MouJsMuwangKind.Penalty)==1,"The same actual returned entity's next owned departure causes exactly one paid penalty and does not recover it a second time.");
  var retained=kept.Skip(1).ToArray();Submit(new EndPlayPhaseCommand(0,game.Revision,P()!.PromptId));Play();
  Need(game.State.TurnNumber>turn&&E<TurnEndedEvent>().Any(e=>e.ActorSeat==0&&e.TurnNumber==turn)&&retained.All(id=>V().Hand.Any(c=>c.Id==id&&c.SkillMarkLabel?.Contains("佐军")==true))&&V().HandCount>=5,"The current TurnEnded does not expire the grants; their two real retained entities were exempt from the real three-card discard limit.");
  var nextTurn=game.State.TurnNumber;var hp=V().Hp;StartZuoJun();var useFrame=F()!.Id;var firstDraw=F()!.MouJuShou!.Bound.ToArray();Answer(c=>c.Parameters.GetValueOrDefault("branch")=="use");Reach(()=>F()?.MouJuShou?.Stage==MouJuShouStage.Use&&P()?.PlayerSeat==0);
  var bound=F()!.MouJuShou!.Bound.ToArray();
  Need(V().Hp==hp-1&&E<ProgramSkillHpLostEvent>().Count(e=>e.FrameId==useFrame&&e.TargetSeat==0&&e.Amount==1)==1&&E<MouJsDrawReturnedEvent>().Where(e=>e.FrameId==useFrame).Select(e=>(e.Requested,e.Actual)).SequenceEqual([(3,3),(1,1)])&&bound.Length==4&&firstDraw.All(bound.Contains),"The second branch pays actual LoseHp1 once, then binds the separate actual Draw1 after the first three.");
  var ownerBefore=SnapshotJson.Serialize(game.CreateSnapshot(0));var peerBefore=SnapshotJson.Serialize(game.CreateSnapshot(2));var movementBefore=game.CardMovements.Count;
  game=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(game.CreateCheckpoint())),registry);
  Need(ownerBefore==SnapshotJson.Serialize(game.CreateSnapshot(0))&&peerBefore==SnapshotJson.Serialize(game.CreateSnapshot(2))&&F()?.Id==useFrame&&F()!.MouJuShou!.Bound.SequenceEqual(bound)&&game.CardMovements.Count==movementBefore&&E<ProgramSkillHpLostEvent>().Count(e=>e.FrameId==useFrame)==1&&E<MouJsDrawReturnedEvent>().Count(e=>e.FrameId==useFrame)==2,"Representative Cold preserves both private views and the exact four bound entities after health/draw payment, without paying or drawing twice.");
  var useChoice=P()!.Choices.First(c=>c.Parameters.GetValueOrDefault("branch")=="use"&&c.Cards.Count==1&&V().Hand.Single(h=>h.Id==c.Cards[0]).Kind==CardKind.DrawTwo);var used=useChoice.Cards.Single();var beforeUse=game.CardMovements.Last().Sequence;Answer(c=>c.Id==useChoice.Id);Reach(()=>F()?.MouJuShou?.Stage==MouJuShouStage.Use&&P()?.PlayerSeat==0);
  var issued=E<MouJsUseIssuedEvent>().Single(e=>e.FrameId==useFrame);var action=E<CardUseAppearanceCapturedEvent>().Select(e=>e.Action).Single(a=>a.ActionId==issued.ActionId);
  Need(action.Type==CardActionType.Use&&action.ActorSeat==0&&action.ProviderSeat==0&&action.PhysicalCards is[{CardId:var actual,From:var from}]&&actual==used&&from==CardLocation.Hand(0)&&action.EffectiveKind==CardKind.DrawTwo&&action.TargetSeats.Count==0&&action.EffectiveDesignatedTargetSeats.Count==0&&game.CardMovements.Where(m=>m.Sequence>beforeUse&&m.From.Zone==CardZoneKind.DrawPile).ToArray() is[{To:var drawOne},{To:var drawTwo}]&&drawOne==CardLocation.Hand(action.ActorSeat)&&drawTwo==CardLocation.Hand(action.ActorSeat)&&E<NullificationResolvedEvent>().Single(e=>e.ResolutionId==issued.UseId)is{EffectCardId:var effectCard,EffectCardKind:CardKind.DrawTwo,EffectNullified:false}&&effectCard==used&&E<CardUseDeclaredEvent>().Count(e=>e.ResolutionId==issued.UseId&&e.CardId==used)==1&&E<CardUseFinishedEvent>().Count(e=>e.ResolutionId==issued.UseId)==1&&E<MouJsUseReturnedEvent>().Count(e=>e.FrameId==useFrame&&e.UseId==issued.UseId)==1,"The chosen bound DrawTwo has implicit self targeting, really draws two cards to its original actor, pays its genuine original Hand material and uses, finishes and returns exactly once to the original paid Zuo Jun frame.");
  var unrelated=V().Hand.Where(c=>!bound.Contains(c.Id)&&!retained.Contains(c.Id)).Select(c=>c.Id).ToHashSet();var leftovers=bound.Where(id=>id!=used&&V().Hand.Any(c=>c.Id==id)).ToArray();var beforeDiscard=game.CardMovements.Last().Sequence;Answer(c=>c.Parameters.GetValueOrDefault("branch")=="done");Play();
  var discarded=E<MouJsMovedEvent>().Where(e=>e.FrameId==useFrame&&e.Sequence>beforeDiscard).ToArray();
  Need(discarded.Select(e=>e.CardId).Order().SequenceEqual(leftovers.Order())&&discarded.All(e=>e.From==CardLocation.Hand(0)&&e.To==CardLocation.DiscardPile)&&discarded.All(e=>!unrelated.Contains(e.CardId))&&E<MouJsCompletedEvent>().Count(e=>e.FrameId==useFrame)==1&&E<MouJsUseIssuedEvent>().Count(e=>e.FrameId==useFrame)==1&&E<ProgramSkillHpLostEvent>().Count(e=>e.FrameId==useFrame)==1,"Completion logically discards only still-held unused bound entities; the DrawTwo's later unrelated gains and already-used material are preserved, and Cold never repeats payment, Use or completion.");
  Need(V().Hand.Any(c=>c.Id==used)&&E<MouJsRecoveredEvent>().Any(e=>e.Turn==nextTurn&&e.CardId==used)&&E<MouJsFirstChosenEvent>().Count(e=>e.Turn==nextTurn)==1,"A real used bound material follows its original Hand-to-Processing invoice into Discard and is recovered once; its Processing completion is not counted as a second owned loss.");
  Submit(new UseProgramSkillCommand(0,Driver,"drop",[used],[],game.Revision,P()!.PromptId));Penalty();
  Submit(new EndPlayPhaseCommand(0,game.Revision,P()!.PromptId));Play();
  Need(E<TurnEndedEvent>().Any(e=>e.ActorSeat==0&&e.TurnNumber==nextTurn)&&retained.All(id=>!V().Hand.Any(c=>c.Id==id&&c.SkillMarkLabel?.Contains("佐军")==true)),"The original grants expire at the recipient's actual next TurnEnded rather than at entry to that turn or an unrelated turn boundary.");
  var transferred=V().Hand.First().Id;var transferTurn=game.State.TurnNumber;Need(game.CreateSnapshot(1).Players[1].HandCount==0,"The native quiet ally has no unrelated Hand material before the controlled real transfer.");Submit(new UseProgramSkillCommand(0,Driver,"give",[transferred],[1],game.Revision,P()!.PromptId));Play();
  Need(game.CardMovements.Any(m=>m.CardId==transferred&&m.From==CardLocation.Hand(0)&&m.To==CardLocation.Hand(1))&&E<MouJsFirstChosenEvent>().Single(e=>e.Turn==transferTurn).CardId==transferred&&!E<MouJsRecoveredEvent>().Any(e=>e.Turn==transferTurn),"The first eligible entity really leaves Ju Shou for another player's Hand and remains tracked without a fabricated return while it is outside Discard.");
  Submit(new UseProgramSkillCommand(0,Driver,"foreign-discard",[],[1],game.Revision,P()!.PromptId));Reach(()=>P()?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="select-and-move-owned-card")==true);Answer(c=>c.Parameters.GetValueOrDefault("slot-index")=="0");Play();
  Need(E<MouJsRecoveredEvent>().Single(e=>e.Turn==transferTurn).CardId==transferred&&game.CardMovements.Count(m=>m.CardId==transferred&&m.From==CardLocation.Hand(1)&&m.To==CardLocation.DiscardPile)==1&&game.CardMovements.Count(m=>m.CardId==transferred&&m.From==CardLocation.DiscardPile&&m.To==CardLocation.Hand(0))==1&&V().Hand.Any(c=>c.Id==transferred),"The user's selected entity-tracking rule follows the exact gifted entity into a later genuine foreign discard within this same actual turn and recovers that card once.");
 }
